CREATE SCHEMA Test;
GO

CREATE SEQUENCE Test.CountBy1 START WITH 1 INCREMENT BY 1;
GO

CREATE SEQUENCE Test.CountByNeg1 START WITH 0 INCREMENT BY-1;
GO

CREATE SEQUENCE SmallSeq AS SMALLINT ;

CREATE SEQUENCE Test.DecSeq
AS DECIMAL(3, 0)
START WITH 125
INCREMENT BY 25
MINVALUE 100
MAXVALUE 200
CYCLE
CACHE 3;

SELECT NEXT VALUE FOR Test.DecSeq;

SELECT cache_size,
       current_value
  FROM sys.sequences
 WHERE name = 'DecSeq';

GRANT CREATE SEQUENCE ON SCHEMA::Test TO [AdventureWorks\Larry];
